import re
names = set()
for line in open('/tmp/fails.txt', encoding='utf-8', errors='replace'):
    line = line.strip().lstrip('❌').strip()
    if line and not line.startswith('FAIL'):
        names.add(line.split(' > ')[0] + ' > ' + (line.split(' > ')[1] if ' > ' in line else ''))
for n in sorted(names)[:20]: print(n)
"

